# Validation regression tests for diagnosticmeta
# Generated by /validate-function diagnosticmeta depth=exhaustive on 2026-09-22

testthat::test_that("C01/C05: Bivariate pooled sensitivity and specificity match independent metafor and mada oracles", {
  testthat::skip_if_not_installed("mada")
  testthat::skip_if_not_installed("metafor")
  
  # Oracle: metafor::rma.mv bivariate mixed model & mada::reitsma on ClinicoPath::diagnosticmeta_test
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d,
    study = "study",
    true_positives = "true_positives",
    false_positives = "false_positives",
    false_negatives = "false_negatives",
    true_negatives = "true_negatives",
    bivariate_analysis = TRUE,
    confidence_level = 95,
    method = "reml"
  )
  biv_df <- res$bivariateresults$asDF
  obs_sens <- biv_df$estimate[biv_df$parameter == "Pooled Sensitivity"]
  obs_spec <- biv_df$estimate[biv_df$parameter == "Pooled Specificity"]
  
  # mada::reitsma oracle
  mada_dat <- data.frame(TP = d$true_positives, FN = d$false_negatives, FP = d$false_positives, TN = d$true_negatives)
  fit_mada <- mada::reitsma(mada_dat, method = "reml")
  coef_mada <- summary(fit_mada)$coefficients
  
  testthat::expect_equal(obs_sens, coef_mada["sensitivity", "Estimate"] * 100, tolerance = 1e-6)
  testthat::expect_equal(obs_spec, (1 - coef_mada["false pos. rate", "Estimate"]) * 100, tolerance = 1e-6)
  testthat::expect_equal(biv_df$ci_lower[biv_df$parameter == "Pooled Sensitivity"], coef_mada["sensitivity", "95%ci.lb"] * 100, tolerance = 1e-6)
  testthat::expect_equal(biv_df$ci_upper[biv_df$parameter == "Pooled Sensitivity"], coef_mada["sensitivity", "95%ci.ub"] * 100, tolerance = 1e-6)
})

testthat::test_that("C09/C12/C15: PLR, NLR, and DOR match independent delta-method formulas", {
  testthat::skip_if_not_installed("mada")
  
  # Oracle: Closed-form delta method from logit sensitivity and logit false-positive rate
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", bivariate_analysis = TRUE
  )
  biv_df <- res$bivariateresults$asDF
  sens <- biv_df$estimate[biv_df$parameter == "Pooled Sensitivity"] / 100
  spec <- biv_df$estimate[biv_df$parameter == "Pooled Specificity"] / 100
  
  plr_expected <- sens / (1 - spec)
  nlr_expected <- (1 - sens) / spec
  dor_expected <- plr_expected / nlr_expected
  
  testthat::expect_equal(biv_df$estimate[biv_df$parameter == "Positive Likelihood Ratio"], plr_expected, tolerance = 1e-6)
  testthat::expect_equal(biv_df$estimate[biv_df$parameter == "Negative Likelihood Ratio"], nlr_expected, tolerance = 1e-6)
  testthat::expect_equal(biv_df$estimate[biv_df$parameter == "Diagnostic Odds Ratio"], dor_expected, tolerance = 1e-6)
})

testthat::test_that("C20/C24/C25/C26: HSROC model parameters theta, tau^2, AUC and delta-method SE", {
  testthat::skip_if_not_installed("mada")
  
  # Oracle: mada::phm and Holling et al. (2012) AUC = 1/(1+theta)
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", hsroc_analysis = TRUE
  )
  hsroc_df <- res$hsrocresults$asDF
  
  mada_dat <- data.frame(TP = d$true_positives, FN = d$false_negatives, FP = d$false_positives, TN = d$true_negatives)
  fit_phm <- mada::phm(mada_dat)
  phm_coef <- coef(fit_phm)
  
  testthat::expect_equal(hsroc_df$estimate[hsroc_df$parameter == "Diagnostic accuracy parameter (theta)"], unname(phm_coef["theta"]), tolerance = 1e-5)
  testthat::expect_equal(hsroc_df$estimate[hsroc_df$parameter == "Between-study variance (tau^2)"], unname(phm_coef["taus_sq"]), tolerance = 1e-5)
  
  auc_expected <- 1 / (1 + phm_coef["theta"])
  theta_se <- sqrt(fit_phm$vcov["theta", "theta"])
  auc_se_expected <- theta_se / (1 + phm_coef["theta"])^2
  
  testthat::expect_equal(hsroc_df$estimate[hsroc_df$parameter == "Area under the SROC curve (AUC = 1/(1 + theta))"], unname(auc_expected), tolerance = 1e-6)
  testthat::expect_equal(hsroc_df$std_error[hsroc_df$parameter == "Area under the SROC curve (AUC = 1/(1 + theta))"], unname(auc_se_expected), tolerance = 1e-6)
})

testthat::test_that("C27-C36: Heterogeneity statistics match metafor univariate rma", {
  testthat::skip_if_not_installed("metafor")
  
  # Oracle: metafor::rma(method = 'REML') on logit sensitivity and logit specificity
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", heterogeneity_analysis = TRUE
  )
  het_df <- res$heterogeneity$asDF
  
  sens <- d$true_positives / (d$true_positives + d$false_negatives)
  v_sens <- 1/d$true_positives + 1/d$false_negatives
  fit_sens <- metafor::rma(yi = stats::qlogis(sens), vi = v_sens, method = "REML")
  
  testthat::expect_equal(het_df$q_statistic[het_df$measure == "Sensitivity"], fit_sens$QE, tolerance = 1e-6)
  testthat::expect_equal(het_df$df[het_df$measure == "Sensitivity"], fit_sens$k - 1)
  testthat::expect_equal(het_df$p_value[het_df$measure == "Sensitivity"], fit_sens$QEp, tolerance = 1e-6)
  testthat::expect_equal(het_df$i_squared[het_df$measure == "Sensitivity"], fit_sens$I2, tolerance = 1e-6)
  testthat::expect_equal(het_df$tau_squared[het_df$measure == "Sensitivity"], fit_sens$tau2, tolerance = 1e-6)
})

testthat::test_that("C37-C40: Meta-regression with covariate matches metafor Knapp-Hartung model", {
  testthat::skip_if_not_installed("metafor")
  
  # Oracle: metafor::rma(mods = ~ year, test = 'knha') on ClinicoPath::diagnosticmeta_test
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", covariate = "year", meta_regression = TRUE
  )
  mreg_df <- res$metaregression$asDF
  mreg_sens_year <- mreg_df[mreg_df$measure == "Sensitivity" & mreg_df$parameter == "year", ]
  
  sens <- d$true_positives / (d$true_positives + d$false_negatives)
  v_sens <- 1/d$true_positives + 1/d$false_negatives
  fit_mreg <- metafor::rma(yi = stats::qlogis(sens), vi = v_sens, mods = ~ year, data = d, method = "REML", test = "knha")
  
  testthat::expect_equal(mreg_sens_year$estimate, fit_mreg$beta[2], tolerance = 1e-6)
  testthat::expect_equal(mreg_sens_year$ci_lower, fit_mreg$ci.lb[2], tolerance = 1e-6)
  testthat::expect_equal(mreg_sens_year$ci_upper, fit_mreg$ci.ub[2], tolerance = 1e-6)
  testthat::expect_equal(mreg_sens_year$p_value, fit_mreg$pval[2], tolerance = 1e-6)
})

testthat::test_that("C41-C43: Deeks publication bias test matches independent weighted least squares", {
  # Oracle: Deeks, Macaskill & Irwig (2005) ESS-weighted linear regression
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", publication_bias = TRUE
  )
  pb_df <- res$publicationbias$asDF
  
  n1 <- d$true_positives + d$false_negatives
  n0 <- d$false_positives + d$true_negatives
  ess <- 4 * n1 * n0 / (n1 + n0)
  log_dor <- log((d$true_positives * d$true_negatives) / (d$false_positives * d$false_negatives))
  inv_root_ess <- 1 / sqrt(ess)
  fit_deeks <- stats::lm(log_dor ~ inv_root_ess, weights = ess)
  cf <- summary(fit_deeks)$coefficients
  
  testthat::expect_equal(pb_df$statistic[1], cf[2, 3], tolerance = 1e-6)
  testthat::expect_equal(pb_df$p_value[1], cf[2, 4], tolerance = 1e-6)
})

testthat::test_that("C44-C45: Individual study sensitivities, specificities, and Wilson score CIs", {
  # Oracle: Closed-form Wilson score interval formula
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", show_individual_studies = TRUE, confidence_level = 95
  )
  ind_df <- res$individualstudies$asDF
  
  for (i in 1:nrow(d)) {
    sens_exp <- d$true_positives[i] / (d$true_positives[i] + d$false_negatives[i]) * 100
    spec_exp <- d$true_negatives[i] / (d$true_negatives[i] + d$false_positives[i]) * 100
    testthat::expect_equal(ind_df$sensitivity[i], sens_exp, tolerance = 1e-6)
    testthat::expect_equal(ind_df$specificity[i], spec_exp, tolerance = 1e-6)
  }
})

testthat::test_that("C46-C47: Predictive values match Bayes theorem exactly", {
  # Oracle: Bayes theorem from pooled sensitivity and specificity
  d <- ClinicoPath::diagnosticmeta_test
  res <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", bivariate_analysis = TRUE, show_interpretation = TRUE
  )
  biv_df <- res$bivariateresults$asDF
  sens <- biv_df$estimate[biv_df$parameter == "Pooled Sensitivity"] / 100
  spec <- biv_df$estimate[biv_df$parameter == "Pooled Specificity"] / 100
  
  pred_df <- res$predictiveValues$asDF
  for (r in seq_len(nrow(pred_df))) {
    prev <- pred_df$prevalence[r]
    ppv_exp <- (sens * prev) / ((sens * prev) + (1 - spec) * (1 - prev))
    npv_exp <- (spec * (1 - prev)) / (((1 - sens) * prev) + spec * (1 - prev))
    testthat::expect_equal(pred_df$ppv[r], ppv_exp, tolerance = 1e-6)
    testthat::expect_equal(pred_df$npv[r], npv_exp, tolerance = 1e-6)
  }
})

testthat::test_that("C01/C05/C15: Metamorphic row-permutation invariance", {
  # Oracle: Metamorphic invariance of meta-analytic summaries under row reordering
  d <- ClinicoPath::diagnosticmeta_test
  set.seed(42)
  d_perm <- d[sample(nrow(d)), ]
  
  res_orig <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", bivariate_analysis = TRUE
  )
  res_perm <- ClinicoPath::diagnosticmeta(
    data = d_perm, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", bivariate_analysis = TRUE
  )
  
  biv_orig <- res_orig$bivariateresults$asDF
  biv_perm <- res_perm$bivariateresults$asDF
  
  testthat::expect_equal(biv_perm$estimate[biv_perm$parameter == "Pooled Sensitivity"],
                         biv_orig$estimate[biv_orig$parameter == "Pooled Sensitivity"], tolerance = 1e-8)
  testthat::expect_equal(biv_perm$estimate[biv_perm$parameter == "Pooled Specificity"],
                         biv_orig$estimate[biv_orig$parameter == "Pooled Specificity"], tolerance = 1e-8)
  testthat::expect_equal(biv_perm$estimate[biv_perm$parameter == "Diagnostic Odds Ratio"],
                         biv_orig$estimate[biv_orig$parameter == "Diagnostic Odds Ratio"], tolerance = 1e-8)
})

