testthat::test_that("C01: Factor counts with values attribute correctly unwrapped", {
  # Oracle: Factor count columns typed nominal in jamovi unwrap values attribute
  d <- ClinicoPath::diagnosticmeta_test
  d_factor <- d
  for (col in c("true_positives", "false_positives", "false_negatives", "true_negatives")) {
    f <- factor(d_factor[[col]])
    attr(f, "values") <- as.numeric(levels(f))
    d_factor[[col]] <- f
  }
  
  res_factor <- ClinicoPath::diagnosticmeta(
    data = d_factor, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", bivariate_analysis = TRUE
  )
  res_orig <- ClinicoPath::diagnosticmeta(
    data = d, study = "study", true_positives = "true_positives",
    false_positives = "false_positives", false_negatives = "false_negatives",
    true_negatives = "true_negatives", bivariate_analysis = TRUE
  )
  
  biv_fac <- res_factor$bivariateresults$asDF
  biv_orig <- res_orig$bivariateresults$asDF
  testthat::expect_equal(biv_fac$estimate[biv_fac$parameter == "Pooled Sensitivity"],
                         biv_orig$estimate[biv_orig$parameter == "Pooled Sensitivity"], tolerance = 1e-8)
})
